(function(){
  'use strict';
  const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const support=$('supportOverlay'),staffOverlay=$('staffAdminOverlay'),supportContent=$('supportContent'),staffContent=$('staffAdminContent'),supportBtn=$('supportBtn'),staffBtn=$('staffAdminBtn');
  if(!support||!staffOverlay||!supportBtn)return;
  const state={me:null,supportTab:'question',supportTickets:[],dashboard:null,staffOpen:false,heartbeat:0,ownerLoaded:false,ownerTimer:0,bugFiles:[],bugPreviewUrls:[],bugRequestId:'',recentErrors:[]};
  const statusLabel={new:'НОВАЯ',in_progress:'В РАБОТЕ',waiting_player:'ОЖИДАЕТСЯ ОТВЕТ',resolved:'РЕШЕНА',fixed:'ИСПРАВЛЕНА',closed:'ЗАКРЫТА',rejected:'ОТКЛОНЕНА',pending:'НА ПРОВЕРКЕ',accepted:'ПРИНЯТ',rejected_report:'ОТКЛОНЁН'};
  const rankName=l=>({1:'HELPER',2:'MODER',3:'ST.MODER',4:'ADMIN',5:'ST.ADMIN',6:'CURATOR',7:'GL.ADMIN',8:'ROOT'}[Number(l)]||'ADMIN');
  const fmtMs=ms=>{const m=Math.floor(Math.max(0,Number(ms)||0)/60000),h=Math.floor(m/60);return h?`${h}ч ${m%60}м`:`${m}м`;};
  const date=v=>v?new Date(Number(v)).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'—';
  async function api(path,options={}){const init={credentials:'same-origin',headers:{...(options.body?{'content-type':'application/json'}:{}),...(options.headers||{})},...options},r=await fetch(path,init);let d={};try{d=await r.json();}catch{}if(!r.ok){const e=new Error(d.error||'SERVER_ERROR');e.code=d.error||'SERVER_ERROR';e.data=d;throw e;}return d;}
  function errorText(e){return ({AUTH_REQUIRED:'Нужно войти в аккаунт.',TARGET_NOT_FOUND:'Игрок не найден.',TARGET_NOT_STAFF:'Этот игрок не является администратором.',DESCRIPTION_REQUIRED:'Добавьте описание.',CANNOT_REPORT_SELF:'Нельзя отправить жалобу на себя.',EVIDENCE_TOO_LARGE:'Скриншоты слишком большие.',TICKET_ALREADY_ASSIGNED:'Обращение уже взял другой администратор.',CLAIM_REQUIRED:'Сначала возьмите обращение в работу.',REASON_REQUIRED:'Укажите причину наказания.',MUTE_LIMIT:'Срок мута превышает лимит вашего ранга.',BAN_LIMIT:'Срок бана превышает лимит вашего ранга.',REPORT_ALREADY_SUBMITTED:'Отчёт за сегодня уже отправлен.',COMMENT_REQUIRED:'При отклонении нужен комментарий.',ADMIN_LOCKED:'Сначала разблокируйте Панель владельца ROOT-кодом.',STAFF_REQUIRED:'Нет прав администратора.',STAFF_SUSPENDED:'Ваши административные права временно приостановлены.',HIERARCHY_DENIED:'Нельзя управлять равным или более высоким рангом.',INSUFFICIENT_LEVEL:'Недостаточный уровень администрации.',NOTE_REQUIRED:'Введите текст замечания.',ACTION_NOT_FOUND:'Действие не найдено.',ACTION_ALREADY_REVOKED:'Действие уже отменено.'}[e.code]||e.code||'Ошибка сервера');}
  function showOverlay(el){$('menu')?.classList.add('hidden');el.classList.remove('hidden');el.setAttribute('aria-hidden','false');}
  function releaseBugPreviews(){state.bugPreviewUrls.forEach(URL.revokeObjectURL);state.bugPreviewUrls=[];state.bugFiles=[];}
  function closeOverlay(el){if(el===support)releaseBugPreviews();el.classList.add('hidden');el.setAttribute('aria-hidden','true');$('menu')?.classList.remove('hidden');}
  async function refreshMe(){
    if(!window.VelocityAccount?.authenticated){state.me=null;staffBtn.classList.add('hidden');return;}
    try{state.me=await api('/api/support/me');if(state.me.staff){staffBtn.classList.remove('hidden');$('staffAdminRank').textContent=`LVL ${state.me.staff.level} · ${rankName(state.me.staff.level)}`;}else staffBtn.classList.add('hidden');}catch{state.me=null;staffBtn.classList.add('hidden');}
  }
  window.addEventListener('error',e=>{const name=e.error?.name;if(name&&/^[A-Za-z][A-Za-z0-9]{0,30}Error$/.test(name)){state.recentErrors.push(name);state.recentErrors=state.recentErrors.slice(-5);}});
  window.addEventListener('velocity-account-changed',()=>setTimeout(refreshMe,0));setTimeout(refreshMe,600);

  function categoryOptions(type){const list=type==='question'?['Игровой процесс','Машины','Аккаунт','Покупки','Свободный режим','Гонки','Кланы','Другое']:type==='player'?['Оскорбления','Спам','Помеха игровому процессу','Использование багов','Читы','Мошенничество','Другое']:['Некорректное наказание','Поведение администратора','Злоупотребление полномочиями','Другое'];return list.map(x=>`<option>${esc(x)}</option>`).join('');}
  function renderSupportForm(type){const title=type==='question'?'ЗАДАТЬ ВОПРОС':type==='player'?'ЖАЛОБА НА ИГРОКА':'ЖАЛОБА НА АДМИНИСТРАТОРА',target=type==='question'?'':`<label class="support-target-field">${type==='admin'?'АДМИНИСТРАТОР':'ИГРОК'}<input id="supportTarget" autocomplete="off" placeholder="@nickname" maxlength="25"></label>`;supportContent.innerHTML=`<form id="supportForm" class="admin-form support-form support-form-${type}"><div class="admin-section-title"><h3>${title}</h3><span>до 3 скриншотов</span></div>${target}<label class="support-category-field">КАТЕГОРИЯ<select id="supportCategory">${categoryOptions(type)}</select></label><label class="support-description-field">ОПИСАНИЕ<textarea id="supportDescription" maxlength="4000" placeholder="Опишите ситуацию подробно…"></textarea></label><label class="support-evidence-field">ДОКАЗАТЕЛЬСТВА<input id="supportEvidence" type="file" accept="image/*" multiple></label><div id="supportFormStatus" class="admin-empty support-form-status"></div><div class="admin-form-actions"><button class="admin-action" type="submit">ОТПРАВИТЬ</button></div></form>`;supportContent.querySelector('#supportForm').addEventListener('submit',e=>submitTicket(e,type));}
  function renderSupportForm(type){if(type==='bug'){renderBugForm();return;}const title=type==='question'?'ЗАДАТЬ ВОПРОС':type==='player'?'ЖАЛОБА НА ИГРОКА':'ЖАЛОБА НА АДМИНИСТРАТОРА',target=type==='question'?'':`<label class="support-target-field">${type==='admin'?'АДМИНИСТРАТОР':'ИГРОК'}<input id="supportTarget" autocomplete="off" placeholder="@nickname" maxlength="25"></label>`;supportContent.innerHTML=`<form id="supportForm" class="admin-form support-form support-form-${type}"><div class="admin-section-title"><h3>${title}</h3><span>до 3 скриншотов</span></div>${target}<label class="support-category-field">КАТЕГОРИЯ<select id="supportCategory">${categoryOptions(type)}</select></label><label class="support-description-field">ОПИСАНИЕ<textarea id="supportDescription" maxlength="4000" placeholder="Опишите ситуацию подробно…"></textarea></label><label class="support-evidence-field">ДОКАЗАТЕЛЬСТВА<input id="supportEvidence" type="file" accept="image/*" multiple></label><div id="supportFormStatus" class="admin-empty support-form-status"></div><div class="admin-form-actions"><button class="admin-action" type="submit">ОТПРАВИТЬ</button></div></form>`;supportContent.querySelector('#supportForm').addEventListener('submit',e=>submitTicket(e,type));}
  function renderBugForm(){releaseBugPreviews();let draft={};try{draft=JSON.parse(sessionStorage.getItem('va-bug-draft')||'{}');}catch{}state.bugRequestId=draft.requestId||crypto.randomUUID();supportContent.innerHTML=`<form id="bugReportForm" class="admin-form support-form"><div class="admin-section-title"><h3>СООБЩИТЬ О БАГЕ</h3><span>до 5 фото · JPEG, PNG, WebP</span></div><label>НАЗВАНИЕ<input id="bugTitle" maxlength="100" required value="${esc(draft.title||'')}" placeholder="Коротко опишите проблему"></label><label>ЧТО ПРОИЗОШЛО<textarea id="bugDescription" maxlength="4000" required placeholder="Опишите ошибку и ожидаемый результат">${esc(draft.description||'')}</textarea></label><label>КАК ПОВТОРИТЬ (НЕОБЯЗАТЕЛЬНО)<textarea id="bugSteps" maxlength="2000" placeholder="Шаги для повторения">${esc(draft.steps||'')}</textarea></label><label>ГДЕ ПРОИЗОШЛО<select id="bugLocation">${['Главное меню','Гараж','Магазин','Карьера','Свободный режим','Онлайн','Кланы','Другое'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>СКРИНШОТЫ<input id="bugImages" type="file" accept="image/jpeg,image/png,image/webp" multiple><small>До 2 МБ на изображение. Вложения доступны только отправителю и владельцу.</small></label><div id="bugPreviews" class="admin-evidence"></div><div id="bugReportStatus" class="admin-empty support-form-status" aria-live="polite"></div><div class="admin-form-actions"><button class="admin-action" type="submit">ОТПРАВИТЬ ОБРАЩЕНИЕ</button></div></form>`;
    const f=$('bugReportForm');$('bugImages').onchange=e=>{const added=Array.from(e.target.files||[]);for(const file of added){if(state.bugFiles.length>=5)break;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>2*1024*1024)continue;state.bugFiles.push(file);}e.target.value='';renderBugPreviews();};f.onsubmit=submitBugReport;
    for(const id of ['bugTitle','bugDescription','bugSteps'])$(id).oninput=()=>{try{sessionStorage.setItem('va-bug-draft',JSON.stringify({requestId:state.bugRequestId,title:$('bugTitle').value,description:$('bugDescription').value,steps:$('bugSteps').value}));}catch{}};
  }
  function renderBugPreviews(){const host=$('bugPreviews');if(!host)return;state.bugPreviewUrls.forEach(URL.revokeObjectURL);state.bugPreviewUrls=[];host.innerHTML=state.bugFiles.map((file,i)=>{const url=URL.createObjectURL(file);state.bugPreviewUrls.push(url);return `<figure class="bug-preview"><img src="${url}" alt="Предпросмотр"><figcaption>${esc(file.name)} <button type="button" data-remove-bug-image="${i}" aria-label="Удалить ${esc(file.name)}">×</button></figcaption></figure>`;}).join('');host.querySelectorAll('[data-remove-bug-image]').forEach(b=>b.onclick=()=>{state.bugFiles.splice(Number(b.dataset.removeBugImage),1);renderBugPreviews();});}
  async function submitBugReport(e){e.preventDefault();const formEl=e.currentTarget,button=formEl.querySelector('[type=submit]'),status=$('bugReportStatus');button.disabled=true;status.textContent='ОТПРАВКА…';let submitted=false;try{const form=new FormData();form.set('requestId',state.bugRequestId);form.set('title',$('bugTitle').value);form.set('description',$('bugDescription').value);form.set('steps',$('bugSteps').value);form.set('location',$('bugLocation').value);const version=window.VelocityVersion||{},ua=navigator.userAgent,screenId=document.querySelector('.overlay:not(.hidden)')?.id||'menu',screenMap={menu:'menu',setup:'setup',career:'career',garage:'garage',shop:'shop',online:'online',friends:'friends',clans:'clans',supportOverlay:'support'};form.set('diagnostics',JSON.stringify({gameVersion:version.published||'2.0.0',build:version.development||'2.0.0',occurredAt:Date.now(),screen:screenMap[screenId]||'menu',device:/iPhone/.test(ua)?'iPhone':/iPad/.test(ua)?'iPad':/Android/.test(ua)?'Android':/Macintosh/.test(ua)?'Macintosh':/Windows/.test(ua)?'Windows':'Linux',browser:/CriOS|Chrome/.test(ua)?'Chrome':/FxiOS|Firefox/.test(ua)?'Firefox':/EdgiOS|Edg/.test(ua)?'Edge':/Safari/.test(ua)?'Safari':'Other',recentErrors:state.recentErrors.slice(-5)}));for(const file of state.bugFiles)form.append('attachments',file,file.name);const response=await fetch('/api/bugs',{method:'POST',credentials:'same-origin',body:form});let data={};try{data=await response.json();}catch{}if(!response.ok){const error=new Error(data.error||'SERVER_ERROR');error.code=data.error;throw error;}status.classList.add('success');status.textContent=`ОБРАЩЕНИЕ #${data.report.no} ПРИНЯТО · СТАТУС: НОВАЯ`;sessionStorage.removeItem('va-bug-draft');state.bugFiles=[];renderBugPreviews();formEl.reset();button.textContent='ПРИНЯТО';submitted=true;}catch(err){status.textContent=({RATE_LIMITED:'Лимит отправки: не более 3 обращений в сутки.',ATTACHMENTS_NOT_CONFIGURED:'Загрузка скриншотов временно недоступна. Удалите вложения и повторите отправку.',INVALID_IMAGE:'Можно прикладывать только корректные JPEG, PNG или WebP.',ATTACHMENT_TOO_LARGE:'Каждое изображение должно быть меньше 2 МБ.',REQUEST_TOO_LARGE:'Суммарный размер вложений слишком велик.'}[err.code]||'Не удалось отправить. Текст формы сохранён на время этой сессии. Проверьте интернет; скриншоты при необходимости выберите повторно.');}finally{button.disabled=submitted;}}
  async function imageData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{const max=1280,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.7));};img.src=reader.result;};reader.readAsDataURL(file);});}
  async function submitTicket(e,type){e.preventDefault();const st=$('supportFormStatus'),btn=e.currentTarget.querySelector('button[type=submit]');btn.disabled=true;st.textContent='ОТПРАВКА…';try{const files=Array.from($('supportEvidence').files||[]).slice(0,3),evidence=[];for(const f of files)evidence.push(await imageData(f));const d=await api('/api/support/tickets',{method:'POST',body:JSON.stringify({type,targetUsername:$('supportTarget')?.value||'',category:$('supportCategory').value,description:$('supportDescription').value,evidence})});const no=Number(d?.ticket?.no)||0;st.classList.add('success');st.textContent=type==='question'?(no?`ВОПРОС #${no} УСПЕШНО ОТПРАВЛЕН`:'ВОПРОС УСПЕШНО ОТПРАВЛЕН'):(no?`ЖАЛОБА #${no} УСПЕШНО ОТПРАВЛЕНА`:'ЖАЛОБА УСПЕШНО ОТПРАВЛЕНА');e.currentTarget.reset();setTimeout(()=>selectSupportTab('mine'),1100);}catch(err){st.textContent=errorText(err);}finally{btn.disabled=false;}}
  async function loadMine(){supportContent.innerHTML='<div class="admin-system-loading">ЗАГРУЗКА…</div>';try{const [d,bugs]=await Promise.all([api('/api/support/tickets'),api('/api/bugs/mine')]);state.supportTickets=d.tickets||[];const bugRows=bugs.reports||[];supportContent.innerHTML=`<div class="admin-section-title"><h3>МОИ ОБРАЩЕНИЯ</h3><span>${state.supportTickets.length+bugRows.length}</span></div><div class="admin-list">${bugRows.map(r=>`<article class="admin-ticket-card"><div><strong>#${r.no} · БАГ-РЕПОРТ · ${esc(r.title)}</strong><p>${esc(r.location)} · ${esc(r.description)}</p><div class="admin-ticket-meta"><span class="admin-chip ${esc(r.status)}">${esc(statusLabel[r.status]||r.status)}</span><span class="admin-chip">${date(r.createdAt)}</span></div>${r.replies.map(x=>`<div class="admin-message owner"><strong>Ответ владельца · ${date(x.createdAt)}</strong><div>${esc(x.message)}</div></div>`).join('')}${r.attachments.length?`<div class="admin-evidence">${r.attachments.map(a=>`<img src="/api/bugs/attachments/${encodeURIComponent(a.id)}" alt="Вложение" loading="lazy">`).join('')}</div>`:''}</div></article>`).join('')}${state.supportTickets.map(ticketCard).join('')||(!bugRows.length?'<div class="admin-empty">Обращений пока нет.</div>':'')}</div>`;supportContent.querySelectorAll('[data-ticket-id]').forEach(b=>b.addEventListener('click',()=>openUserTicket(b.dataset.ticketId)));}catch(e){supportContent.innerHTML=`<div class="admin-empty">${esc(errorText(e))}</div>`;}}
  function ticketCard(t){const who=t.type==='question'?'ВОПРОС':t.type==='player'?`НА @${esc(t.target)}`:`НА ADMIN @${esc(t.targetAdmin)}`;return `<article class="admin-ticket-card"><div><strong>#${t.no} · ${who}</strong><p>${esc(t.category)} · ${esc(t.description.slice(0,130))}</p><div class="admin-ticket-meta"><span class="admin-chip ${esc(t.status)}">${esc(statusLabel[t.status]||t.status)}</span>${t.assignedAdmin?`<span class="admin-chip">@${esc(t.assignedAdmin)}</span>`:''}<span class="admin-chip">${date(t.createdAt)}</span></div></div><button class="admin-action muted" data-ticket-id="${esc(t.id)}">ОТКРЫТЬ</button></article>`;}
  async function openUserTicket(id){supportContent.innerHTML='<div class="admin-system-loading">ЗАГРУЗКА…</div>';try{const d=await api('/api/support/tickets/'+id),t=d.ticket;supportContent.innerHTML=`<div class="admin-ticket-detail"><div class="admin-row-actions"><button id="backMine" class="admin-action muted">← МОИ ОБРАЩЕНИЯ</button></div>${ticketDetailHtml(t,d.messages)}${!['resolved','rejected'].includes(t.status)?`<form id="userTicketReply" class="admin-form"><label>ДОПОЛНИТЬ ОБРАЩЕНИЕ<textarea id="userReplyText" maxlength="2000"></textarea></label><button class="admin-action" type="submit">ОТПРАВИТЬ</button></form>`:''}</div>`;$('backMine').onclick=loadMine;const f=$('userTicketReply');if(f)f.onsubmit=async e=>{e.preventDefault();try{await api(`/api/support/tickets/${id}/reply`,{method:'POST',body:JSON.stringify({message:$('userReplyText').value})});openUserTicket(id);}catch(err){alert(errorText(err));}};}catch(e){supportContent.innerHTML=`<div class="admin-empty">${esc(errorText(e))}</div>`;}}
  function ticketDetailHtml(t,messages=[]){const ev=(t.evidence||[]).length?`<div class="admin-evidence">${t.evidence.map(x=>`<img src="${esc(x)}" alt="Доказательство">`).join('')}</div>`:'';return `<div class="admin-ticket-body"><div class="admin-ticket-meta"><span class="admin-chip ${esc(t.status)}">${esc(statusLabel[t.status]||t.status)}</span><span class="admin-chip">#${t.no}</span><span class="admin-chip">${esc(t.category)}</span></div><p>${esc(t.description)}</p>${ev}</div><div class="admin-chat">${messages.map(m=>`<div class="admin-message ${esc(m.role)}"><strong>@${esc(m.author)}</strong><div>${esc(m.message)}</div><small>${date(m.createdAt)}</small></div>`).join('')}</div>`;}
  function selectSupportTab(tab){const previous=state.supportTab;if(previous==='bug'&&tab!=='bug')releaseBugPreviews();state.supportTab=tab;document.querySelectorAll('#supportTabs [data-support-tab]').forEach(b=>b.classList.toggle('active',b.dataset.supportTab===tab));if(tab==='mine')loadMine();else if(tab==='account'||tab==='other')supportContent.innerHTML=`<div class="admin-empty"><h3>${tab==='account'?'ПРОБЛЕМА С АККАУНТОМ':'ДРУГАЯ ПРОБЛЕМА'}</h3><p>Эта категория пока не принимает обращения. Для ошибки игры используйте «Сообщить о баге», для вопроса по аккаунту — «Вопрос».</p></div>`;else renderSupportForm(tab);}
  $('supportTabs').addEventListener('click',e=>{const b=e.target.closest('[data-support-tab]');if(b)selectSupportTab(b.dataset.supportTab);});supportBtn.addEventListener('click',async()=>{await refreshMe();showOverlay(support);selectSupportTab('question');});$('supportCloseBtn').onclick=()=>closeOverlay(support);

  function dashboardStats(d){const s=d.snapshot;return `<div class="admin-system-grid"><div class="admin-stat"><small>РАНГ</small><strong>LVL ${d.staff.level}</strong><span>${esc(rankName(d.staff.level))}</span></div><div class="admin-stat"><small>БАЛЛЫ</small><strong>${s.points}/${s.norm}</strong><span>${s.completion}% нормы</span></div><div class="admin-stat"><small>ADMIN ONLINE</small><strong>${fmtMs(s.activeMs)}</strong><span>активное дежурство</span></div><div class="admin-stat"><small>ЗАРПЛАТА</small><strong>${Number(s.amount).toLocaleString('ru-RU')}</strong><span>${s.percent}% базы</span></div></div>`;}
  async function openStaff(){showOverlay(staffOverlay);state.staffOpen=true;startHeartbeat();await loadStaff();}
  function closeStaff(){state.staffOpen=false;stopHeartbeat();closeOverlay(staffOverlay);}
  function startHeartbeat(){stopHeartbeat();const beat=()=>api('/api/staff-admin/heartbeat',{method:'POST',body:'{}'}).catch(()=>{});beat();state.heartbeat=setInterval(beat,60000);}function stopHeartbeat(){if(state.heartbeat){clearInterval(state.heartbeat);state.heartbeat=0;}}
  function staffToolsHtml(level){
    const items=[];
    if(level>=5)items.push('<button id="staffManagementBtn" class="admin-action muted" type="button">СОСТАВ · КОНТРОЛЬ</button>');
    if(level>=7)items.push('<button id="staffControlBtn" class="admin-action muted" type="button">CONTROL CENTER</button>');
    if(level>=8)items.push('<button id="staffDiagnosticsBtn" class="admin-action muted" type="button">ROOT DIAGNOSTICS</button>');
    return items.length?`<section class="admin-command-strip"><div><small>ДОПОЛНИТЕЛЬНЫЕ ПРАВА</small><strong>${esc(rankName(level))}</strong></div><div>${items.join('')}</div></section>`:'';
  }
  async function loadStaff(){staffContent.innerHTML='<div class="admin-system-loading">ЗАГРУЗКА ADMIN PANEL…</div>';try{const d=await api('/api/staff-admin/dashboard');state.dashboard=d;$('staffAdminSubtitle').textContent=`LVL ${d.staff.level} · ${rankName(d.staff.level)} · выговоров: ${d.staff.warnings.length}`;const qs=d.tickets.filter(x=>x.type==='question'),rs=d.tickets.filter(x=>x.type==='player');staffContent.innerHTML=`${dashboardStats(d)}${staffToolsHtml(d.staff.level)}<div class="admin-section-title"><h3>ВОПРОСЫ</h3><span>${qs.length} в очереди</span></div><div class="admin-list">${qs.length?qs.map(adminTicketCard).join(''):'<div class="admin-empty">Новых вопросов нет.</div>'}</div>${d.staff.level>=2?`<div class="admin-section-title"><h3>ЖАЛОБЫ НА ИГРОКОВ</h3><span>${rs.length} в очереди</span></div><div class="admin-list">${rs.length?rs.map(adminTicketCard).join(''):'<div class="admin-empty">Новых жалоб нет.</div>'}</div>`:''}<div class="admin-section-title"><h3>ОТЧЁТНОСТЬ</h3><span>ежедневный отчёт</span></div><div id="staffReportsBox"><button id="loadStaffReports" class="admin-action muted">ИСТОРИЯ ОТЧЁТОВ</button> <button id="submitStaffReport" class="admin-action">ОТПРАВИТЬ ОТЧЁТ ЗА СЕГОДНЯ</button></div>`;staffContent.querySelectorAll('[data-admin-ticket]').forEach(b=>b.onclick=()=>openAdminTicket(b.dataset.adminTicket));$('loadStaffReports').onclick=renderStaffReports;$('submitStaffReport').onclick=submitStaffReport;const mg=$('staffManagementBtn');if(mg)mg.onclick=openStaffManagement;const ctl=$('staffControlBtn');if(ctl)ctl.onclick=openStaffControl;const dg=$('staffDiagnosticsBtn');if(dg)dg.onclick=openStaffDiagnostics;}catch(e){staffContent.innerHTML=`<div class="admin-empty">${esc(errorText(e))}</div>`;}}
  function adminTicketCard(t){return `<article class="admin-ticket-card"><div><strong>#${t.no} · ${t.type==='question'?'ВОПРОС':`ЖАЛОБА НА @${esc(t.target)}`}</strong><p>@${esc(t.reporter)} · ${esc(t.category)} · ${esc(t.description.slice(0,120))}</p><div class="admin-ticket-meta"><span class="admin-chip ${esc(t.status)}">${esc(statusLabel[t.status]||t.status)}</span>${t.assignedAdmin?`<span class="admin-chip">Рассматривает @${esc(t.assignedAdmin)}</span>`:''}</div></div><button data-admin-ticket="${esc(t.id)}" class="admin-action muted">ОТКРЫТЬ</button></article>`;}
  async function openAdminTicket(id){staffContent.innerHTML='<div class="admin-system-loading">ЗАГРУЗКА…</div>';try{const d=await api('/api/staff-admin/tickets/'+id),t=d.ticket,l=state.dashboard?.staff?.level||1,owned=t.assignedAdminId===window.VelocityAccount?.user?.id;staffContent.innerHTML=`<div class="admin-row-actions"><button id="adminTicketBack" class="admin-action muted">← ОЧЕРЕДЬ</button>${!t.assignedAdminId?'<button id="adminTicketClaim" class="admin-action">ВЗЯТЬ В РАБОТУ</button>':''}</div><div class="admin-ticket-detail">${ticketDetailHtml(t,d.messages)}${owned&&!['resolved','rejected'].includes(t.status)?`<form id="adminReplyForm" class="admin-form"><label>ОТВЕТ<textarea id="adminReplyText" maxlength="2000"></textarea></label><div class="admin-form-actions"><button class="admin-action" type="submit">ОТВЕТИТЬ</button><button id="adminWaitPlayer" class="admin-action muted" type="button">ЗАПРОСИТЬ УТОЧНЕНИЕ</button><button id="adminResolve" class="admin-action" type="button">ЗАКРЫТЬ</button><button id="adminReject" class="admin-action danger" type="button">ОТКЛОНИТЬ</button></div></form>${t.type==='player'&&l>=2?punishHtml(l):''}`:''}</div>`;$('adminTicketBack').onclick=loadStaff;const claim=$('adminTicketClaim');if(claim)claim.onclick=async()=>{try{await api(`/api/staff-admin/tickets/${id}/claim`,{method:'POST',body:'{}'});openAdminTicket(id);}catch(e){alert(errorText(e));loadStaff();}};const f=$('adminReplyForm');if(f){f.onsubmit=e=>{e.preventDefault();sendAdminMessage(id,false)};$('adminWaitPlayer').onclick=()=>sendAdminMessage(id,true);$('adminResolve').onclick=()=>resolveAdminTicket(id,'resolved');$('adminReject').onclick=()=>resolveAdminTicket(id,'rejected');const pb=$('adminPunish');if(pb)pb.onclick=()=>punish(id,l);}}catch(e){staffContent.innerHTML=`<div class="admin-empty">${esc(errorText(e))}</div>`;}}
  function punishHtml(level){return `<div class="admin-punish-box"><select id="punishAction"><option value="warning">ПРЕДУПРЕЖДЕНИЕ</option><option value="mute">МУТ</option>${level>=4?'<option value="ban">БАН</option>':''}</select><input id="punishDuration" type="number" min="1" value="60"><select id="punishUnit"><option value="60000">МИН</option><option value="3600000">ЧАС</option><option value="86400000">ДЕНЬ</option>${level>=8?'<option value="permanent">PERMANENT</option>':''}</select><input id="punishReason" maxlength="240" placeholder="Причина наказания"><button id="adminPunish" class="admin-action danger">ВЫДАТЬ</button></div>`;}
  async function sendAdminMessage(id,waiting){const text=$('adminReplyText').value.trim();if(!text)return;try{await api(`/api/staff-admin/tickets/${id}/message`,{method:'POST',body:JSON.stringify({message:text,waitingPlayer:waiting})});openAdminTicket(id);}catch(e){alert(errorText(e));}}
  async function resolveAdminTicket(id,status){try{await api(`/api/staff-admin/tickets/${id}/resolve`,{method:'POST',body:JSON.stringify({status,message:$('adminReplyText')?.value||''})});loadStaff();}catch(e){alert(errorText(e));}}
  async function punish(id){const action=$('punishAction').value,reason=$('punishReason').value.trim(),unit=$('punishUnit').value,permanent=action==='ban'&&unit==='permanent',durationMs=action==='warning'?0:permanent?0:Math.max(0,Number($('punishDuration').value))*Number(unit);try{await api(`/api/staff-admin/tickets/${id}/punish`,{method:'POST',body:JSON.stringify({action,reason,durationMs,permanent})});alert('Наказание выдано и записано в историю.');openAdminTicket(id);}catch(e){alert(errorText(e));}}
  async function renderStaffReports(){try{const d=await api('/api/staff-admin/reports'),box=$('staffReportsBox');box.innerHTML=(d.reports||[]).length?`<div class="admin-list">${d.reports.map(r=>`<article class="admin-report-card"><strong>${esc(r.day)} · ${esc(statusLabel[r.status]||r.status.toUpperCase())}</strong><p>${r.snapshot.points||0}/${r.snapshot.norm||0} баллов · ${fmtMs(r.snapshot.activeMs)} · ${Number(r.paidAmount||r.calculatedSalary).toLocaleString('ru-RU')} CR</p>${r.ownerComment?`<p>Owner: ${esc(r.ownerComment)}</p>`:''}</article>`).join('')}</div>`:'<div class="admin-empty">Истории ещё нет.</div>';}catch(e){alert(errorText(e));}}
  async function submitStaffReport(){try{const d=await api('/api/staff-admin/report/submit',{method:'POST',body:'{}'});alert(`Отчёт отправлен. Расчётная зарплата: ${d.report.calculatedSalary} CR`);renderStaffReports();}catch(e){alert(errorText(e));}}

  function managerStaffCard(a,actor){
    const canEdit=actor.level>=6&&a.level<=actor.manageBelow,rankOptions=Array.from({length:Math.max(0,actor.manageBelow)},(_,i)=>i+1).map(l=>`<option value="${l}" ${l===a.level?'selected':''}>LVL ${l} · ${rankName(l)}</option>`).join('');
    return `<article class="admin-staff-card ${a.online?'online':''} ${a.suspended?'suspended':''}"><div class="admin-staff-head"><div><strong>@${esc(a.username)} · LVL ${a.level} · ${esc(rankName(a.level))}</strong><p>${a.suspended?`ОТСТРАНЁН ДО ${date(a.suspendedUntil)} · ${esc(a.suspensionReason)}`:`Сегодня: ${fmtMs(a.work.activeMs)} · вопросы ${a.work.questions} · жалобы ${a.work.reports} · приглашено ${a.work.referrals}`}</p></div>${a.online?'<span class="admin-online-dot"></span>':''}</div><div class="admin-row-actions"><button class="admin-action muted" data-mgr-note="${a.id}">ЗАМЕЧАНИЕ</button>${canEdit?`<select data-mgr-rank-select="${a.id}">${rankOptions}</select><button class="admin-action muted" data-mgr-rank="${a.id}">РАНГ</button><button class="admin-action danger" data-mgr-warning="${a.id}">ВЫГОВОР</button>${a.suspended?`<button class="admin-action" data-mgr-resume="${a.id}">ВОССТАНОВИТЬ</button>`:`<button class="admin-action danger" data-mgr-suspend="${a.id}">ОТСТРАНИТЬ</button>`}<button class="admin-action danger" data-mgr-remove="${a.id}">СНЯТЬ</button>`:''}</div>${a.notes?.length?`<div class="admin-note-list">${a.notes.slice(0,3).map(n=>`<small>${date(n.createdAt)} · @${esc(n.createdByUsername||'admin')}: ${esc(n.note)}</small>`).join('')}</div>`:''}</article>`;
  }
  async function openStaffManagement(){
    staffContent.innerHTML='<div class="admin-system-loading">ЗАГРУЗКА СОСТАВА…</div>';
    try{
      const d=await api('/api/staff-admin/management/summary'),actor=d.actor;
      staffContent.innerHTML=`<div class="admin-row-actions admin-sticky-actions"><button id="mgrBack" class="admin-action muted">← ADMIN PANEL</button></div><div class="admin-section-title"><h3>СОСТАВ И КОНТРОЛЬ</h3><span>${rankName(actor.level)} · управление до LVL ${actor.manageBelow||0}</span></div>${actor.level>=6?`<section class="owner-admin-section"><div class="owner-admin-assignment"><input id="mgrUsername" placeholder="@nickname"><select id="mgrLevel">${Array.from({length:actor.manageBelow},(_,i)=>i+1).map(l=>`<option value="${l}">LVL ${l} · ${rankName(l)}</option>`).join('')}</select><button id="mgrAssign" class="admin-action">НАЗНАЧИТЬ</button></div></section>`:''}<div class="owner-admin-staff-grid">${d.staff.length?d.staff.map(a=>managerStaffCard(a,actor)).join(''):'<div class="admin-empty">Нет доступных администраторов.</div>'}</div>${actor.level>=6?`<div class="admin-section-title"><h3>ОТЧЁТЫ МЛАДШИХ</h3><span>${d.reports.length}</span></div><div class="admin-list">${d.reports.length?d.reports.map(r=>`<article class="admin-report-card"><strong>@${esc(r.username)} · LVL ${r.level} · ${esc(r.day)}</strong><p>${r.snapshot.points||0}/${r.snapshot.norm||0} баллов · ${fmtMs(r.snapshot.activeMs)} · ${Number(r.calculatedSalary).toLocaleString('ru-RU')} CR</p><div class="admin-row-actions"><button class="admin-action" data-mgr-report="${r.id}" data-decision="accepted">ПРИНЯТЬ</button><button class="admin-action danger" data-mgr-report="${r.id}" data-decision="rejected">ОТКЛОНИТЬ</button></div></article>`).join(''):'<div class="admin-empty">Нет отчётов на проверку.</div>'}</div>`:''}<div class="admin-section-title"><h3>ДЕЙСТВИЯ МЛАДШИХ</h3><span>можно отменить ошибочное наказание</span></div><div class="admin-list">${d.actions.length?d.actions.slice(0,40).map(a=>`<article class="admin-report-card"><strong>${esc(a.action.toUpperCase())} · @${esc(a.admin)} → @${esc(a.target||'—')}</strong><p>${esc(a.reason)} · ${date(a.createdAt)}${a.revokedAt?' · ОТМЕНЕНО':''}</p>${!a.revokedAt?`<button class="admin-action muted" data-mgr-revoke="${a.id}">ОТМЕНИТЬ ДЕЙСТВИЕ</button>`:''}</article>`).join(''):'<div class="admin-empty">Действий пока нет.</div>'}</div>`;
      $('mgrBack').onclick=loadStaff;
      const assign=$('mgrAssign');if(assign)assign.onclick=async()=>{try{await api('/api/staff-admin/management/assign',{method:'POST',body:JSON.stringify({username:$('mgrUsername').value,level:Number($('mgrLevel').value)})});openStaffManagement();}catch(e){alert(errorText(e));}};
      staffContent.querySelectorAll('[data-mgr-note]').forEach(b=>b.onclick=async()=>{const note=prompt('Замечание администратору:');if(!note)return;try{await api(`/api/staff-admin/management/staff/${b.dataset.mgrNote}/note`,{method:'POST',body:JSON.stringify({note})});openStaffManagement();}catch(e){alert(errorText(e));}});
      staffContent.querySelectorAll('[data-mgr-rank]').forEach(b=>b.onclick=async()=>{const id=b.dataset.mgrRank,sel=staffContent.querySelector(`[data-mgr-rank-select="${id}"]`);try{await api(`/api/staff-admin/management/staff/${id}/rank`,{method:'POST',body:JSON.stringify({level:Number(sel.value)})});openStaffManagement();}catch(e){alert(errorText(e));}});
      staffContent.querySelectorAll('[data-mgr-warning]').forEach(b=>b.onclick=async()=>{const reason=prompt('Причина выговора:');if(!reason)return;try{await api(`/api/staff-admin/management/staff/${b.dataset.mgrWarning}/warning`,{method:'POST',body:JSON.stringify({reason})});openStaffManagement();}catch(e){alert(errorText(e));}});
      staffContent.querySelectorAll('[data-mgr-suspend]').forEach(b=>b.onclick=async()=>{const reason=prompt('Причина отстранения:');if(!reason)return;const hours=Math.max(1,Number(prompt('На сколько часов? (1–720)','24'))||24);try{await api(`/api/staff-admin/management/staff/${b.dataset.mgrSuspend}/suspend`,{method:'POST',body:JSON.stringify({reason,durationMs:Math.min(720,hours)*3600000})});openStaffManagement();}catch(e){alert(errorText(e));}});
      staffContent.querySelectorAll('[data-mgr-resume]').forEach(b=>b.onclick=async()=>{try{await api(`/api/staff-admin/management/staff/${b.dataset.mgrResume}/resume`,{method:'POST',body:'{}'});openStaffManagement();}catch(e){alert(errorText(e));}});
      staffContent.querySelectorAll('[data-mgr-remove]').forEach(b=>b.onclick=async()=>{if(!confirm('Снять администратора?'))return;try{await api(`/api/staff-admin/management/staff/${b.dataset.mgrRemove}/remove`,{method:'POST',body:'{}'});openStaffManagement();}catch(e){alert(errorText(e));}});
      staffContent.querySelectorAll('[data-mgr-report]').forEach(b=>b.onclick=async()=>{let comment='';if(b.dataset.decision==='rejected'){comment=prompt('Причина отклонения:')||'';if(!comment.trim())return;}try{const x=await api(`/api/staff-admin/management/reports/${b.dataset.mgrReport}/review`,{method:'POST',body:JSON.stringify({decision:b.dataset.decision,comment})});alert(b.dataset.decision==='accepted'?`Выплачено ${x.paidAmount} CR`:'Отчёт отклонён');openStaffManagement();}catch(e){alert(errorText(e));}});
      staffContent.querySelectorAll('[data-mgr-revoke]').forEach(b=>b.onclick=async()=>{if(!confirm('Отменить это наказание?'))return;try{await api(`/api/staff-admin/management/actions/${b.dataset.mgrRevoke}/revoke`,{method:'POST',body:'{}'});openStaffManagement();}catch(e){alert(errorText(e));}});
    }catch(e){staffContent.innerHTML=`<div class="admin-empty">${esc(errorText(e))}</div>`;}
  }
  function serverCard(s){
    const players=s.players||[];return `<article class="admin-server-card"><div class="admin-staff-head"><div><strong>${esc(s.server||s.serverId||'SERVER')}</strong><p>${players.length}/50 игроков · ивенты ${s.eventsDisabled?'ОТКЛЮЧЕНЫ':'ВКЛЮЧЕНЫ'}</p></div><span class="admin-chip">${s.ok?'ONLINE':'ERROR'}</span></div><div class="admin-server-players">${players.length?players.map(p=>`<div><span>@${esc(String(p.name||'').replace(/^@/,''))} ${p.adminLevel?`· ${rankName(p.adminLevel)}`:''}</span>${p.userId?`<button class="admin-action danger" data-control-kick="${esc(String(p.name||'').replace(/^@/,''))}">KICK</button>`:''}</div>`).join(''):'<small>Сервер пуст.</small>'}</div></article>`;
  }
  async function openStaffControl(){
    staffContent.innerHTML='<div class="admin-system-loading">ЗАГРУЗКА CONTROL CENTER…</div>';
    try{
      const d=await api('/api/staff-admin/control/servers'),level=state.dashboard?.staff?.level||7;
      staffContent.innerHTML=`<div class="admin-row-actions admin-sticky-actions"><button id="controlBack" class="admin-action muted">← ADMIN PANEL</button></div><div class="admin-section-title"><h3>CONTROL CENTER</h3><span>GL.ADMIN / ROOT</span></div><section class="admin-control-toolbar"><input id="controlAnnouncement" maxlength="220" placeholder="Глобальное объявление всем 3 серверам"><button id="controlAnnounce" class="admin-action">ОТПРАВИТЬ</button><button id="controlClearEvents" class="admin-action danger">ОСТАНОВИТЬ АКТИВНОСТИ</button></section><div class="admin-server-grid">${(d.servers||[]).map(serverCard).join('')}</div><section class="owner-admin-section"><div class="admin-section-title"><h3>ПРОФИЛЬ ИГРОКА</h3><span>расширенный просмотр</span></div><div class="admin-control-toolbar"><input id="controlProfileName" placeholder="@nickname"><button id="controlProfileFind" class="admin-action muted">НАЙТИ</button></div><div id="controlProfileResult"></div></section><section class="owner-admin-section"><div class="admin-section-title"><h3>LOGS</h3><span>последние события</span></div><div class="admin-control-toolbar"><input id="controlLogsQ" placeholder="ник / событие / сервер"><select id="controlLogsCategory"><option value="all">ВСЕ</option><option value="blocks">БЛОКИРОВКИ</option><option value="mutes">МУТЫ</option><option value="joins">ЗАХОДЫ</option><option value="purchases">ПОКУПКИ</option><option value="sales">ПРОДАЖИ</option><option value="system">СИСТЕМА</option><option value="chat">ЧАТ</option></select><button id="controlLogsFind" class="admin-action muted">ПОКАЗАТЬ</button></div><div id="controlLogsResult"></div></section>${level>=8?'<div class="admin-row-actions"><button id="controlEventsOff" class="admin-action danger">ROOT · ОТКЛЮЧИТЬ ИВЕНТЫ</button><button id="controlEventsOn" class="admin-action">ROOT · ВКЛЮЧИТЬ ИВЕНТЫ</button></div>':''}`;
      $('controlBack').onclick=loadStaff;
      staffContent.querySelectorAll('[data-control-kick]').forEach(b=>b.onclick=async()=>{const reason=prompt(`Причина отключения @${b.dataset.controlKick}:`,'Нарушение правил')||'';if(!reason)return;try{await api('/api/staff-admin/control/kick',{method:'POST',body:JSON.stringify({username:b.dataset.controlKick,reason})});openStaffControl();}catch(e){alert(errorText(e));}});
      $('controlAnnounce').onclick=async()=>{try{await api('/api/staff-admin/control/announce',{method:'POST',body:JSON.stringify({message:$('controlAnnouncement').value})});alert('Объявление отправлено.');}catch(e){alert(errorText(e));}};
      $('controlClearEvents').onclick=async()=>{if(!confirm('Остановить активные игровые события на всех серверах?'))return;try{await api('/api/staff-admin/control/clear-events',{method:'POST',body:'{}'});openStaffControl();}catch(e){alert(errorText(e));}};
      $('controlProfileFind').onclick=async()=>{const box=$('controlProfileResult');box.innerHTML='Загрузка…';try{const x=await api('/api/staff-admin/control/profile?username='+encodeURIComponent($('controlProfileName').value));const p=x.profile;box.innerHTML=`<article class="admin-profile-card"><strong>@${esc(p.user.username)}</strong><p>CR: ${Number(p.save.credits).toLocaleString('ru-RU')} · машин: ${p.save.ownedLiveries.length} · эффектов: ${p.save.ownedEffects.length} · рефералы: ${p.referrals.rewarded}/${p.referrals.total}</p><p>${p.ban?`БАН до ${date(p.ban.expiresAt)} · ${esc(p.ban.reason)}`:'Активной блокировки нет'}${p.staff?` · ADMIN LVL ${p.staff.level} ${rankName(p.staff.level)}`:''}</p></article>`;}catch(e){box.innerHTML=`<div class="admin-empty">${esc(errorText(e))}</div>`;}};
      $('controlLogsFind').onclick=async()=>{const box=$('controlLogsResult');box.innerHTML='Загрузка…';try{const x=await api('/api/staff-admin/control/logs?q='+encodeURIComponent($('controlLogsQ').value)+'&category='+encodeURIComponent($('controlLogsCategory').value)+'&limit=40');box.innerHTML=`<div class="admin-log-mini">${(x.items||[]).map(i=>`<article><strong>${esc(i.eventType)} · ${esc(i.actorUsername||i.actorRole)}</strong><span>${date(i.createdAt)} · ${esc(i.serverId||i.category)}</span><p>${esc(i.subject||i.message||i.reason||'')}</p></article>`).join('')||'<div class="admin-empty">Нет событий.</div>'}</div>`;}catch(e){box.innerHTML=`<div class="admin-empty">${esc(errorText(e))}</div>`;}};
      const off=$('controlEventsOff'),on=$('controlEventsOn');if(off)off.onclick=()=>setEventsDisabled(true);if(on)on.onclick=()=>setEventsDisabled(false);
    }catch(e){staffContent.innerHTML=`<div class="admin-empty">${esc(errorText(e))}</div>`;}
  }
  async function setEventsDisabled(disabled){try{await api('/api/staff-admin/control/events-disabled',{method:'POST',body:JSON.stringify({disabled})});openStaffControl();}catch(e){alert(errorText(e));}}
  async function openStaffDiagnostics(){
    staffContent.innerHTML='<div class="admin-system-loading">ROOT DIAGNOSTICS…</div>';
    try{const d=await api('/api/staff-admin/control/diagnostics'),x=d.diagnostics;staffContent.innerHTML=`<div class="admin-row-actions admin-sticky-actions"><button id="diagBack" class="admin-action muted">← ADMIN PANEL</button></div><div class="admin-section-title"><h3>ROOT DIAGNOSTICS</h3><span>только игровые системы · без OWNER/YooMoney</span></div><div class="admin-system-grid"><div class="admin-stat"><small>АККАУНТЫ</small><strong>${x.users}</strong></div><div class="admin-stat"><small>ОБРАЩЕНИЯ</small><strong>${x.openTickets}</strong></div><div class="admin-stat"><small>ОТЧЁТЫ</small><strong>${x.pendingReports}</strong></div><div class="admin-stat"><small>ADMIN</small><strong>${x.activeStaff}</strong></div></div><div class="admin-server-grid">${(x.servers||[]).map(serverCard).join('')}</div>`;$('diagBack').onclick=loadStaff;}catch(e){staffContent.innerHTML=`<div class="admin-empty">${esc(errorText(e))}</div>`;}
  }

  staffBtn.addEventListener('click',openStaff);$('staffAdminCloseBtn').onclick=closeStaff;

  async function openOwner(silent=false){const host=$('ownerAdminSystem');if(!host)return;if(!silent)host.innerHTML='<div class="admin-system-loading">ЗАГРУЗКА АДМИНИСТРАЦИИ…</div>';try{const [sum,reports,complaints,bugs]=await Promise.all([api('/api/admin-system/owner/summary'),api('/api/admin-system/owner/reports'),api('/api/admin-system/owner/admin-complaints'),api('/api/bugs/owner')]);renderOwner(host,sum,reports,complaints);renderOwnerBugs(host,bugs);clearInterval(state.ownerTimer);state.ownerTimer=setInterval(()=>{if(!document.hidden&&host.offsetParent!==null)openOwner(true);},30000);}catch(e){if(!silent)host.innerHTML=`<div class="admin-empty">${esc(errorText(e))}</div>`;}}
  function renderOwnerBugs(host,data){let section=host.querySelector('#ownerBugReports');if(!section){section=document.createElement('section');section.id='ownerBugReports';section.className='owner-admin-section';host.append(section);}const reports=data.reports||[];section.innerHTML=`<div class="admin-section-title"><h3>ЖАЛОБЫ И БАГ-РЕПОРТЫ <span class="admin-chip">НОВЫХ: ${Number(data.unread)||0}</span></h3><span>${reports.length} обращений</span></div><div class="admin-row-actions"><select id="bugStatusFilter"><option value="">Все статусы</option>${['new','in_progress','fixed','closed','rejected'].map(s=>`<option value="${s}">${s}</option>`).join('')}</select><select id="bugLocationFilter"><option value="">Все разделы</option>${['Главное меню','Гараж','Магазин','Карьера','Свободный режим','Онлайн','Кланы','Другое'].map(s=>`<option>${s}</option>`).join('')}</select><input type="date" id="bugDateFilter" aria-label="Дата обращения"><input type="search" id="bugPlayerFilter" placeholder="Игрок"><button class="admin-action muted" id="reloadBugReports">ОБНОВИТЬ</button></div><div class="admin-list">${reports.length?reports.map(r=>`<article class="admin-ticket-card"><div><strong>#${r.no} · ${esc(r.title)} · @${esc(r.username)}</strong><p>${esc(r.location)} · ${date(r.createdAt)} · ${esc(r.description)}</p>${r.steps?`<p><b>Повторение:</b> ${esc(r.steps)}</p>`:''}<small>Игрок ${esc(r.playerId)} · ${esc(r.diagnostics.gameVersion||'')} / ${esc(r.diagnostics.build||'')}</small>${r.attachments.length?`<div class="admin-evidence">${r.attachments.map(a=>`<a href="/api/bugs/attachments/${encodeURIComponent(a.id)}" target="_blank" rel="noopener"><img src="/api/bugs/attachments/${encodeURIComponent(a.id)}" alt="Вложение #${r.no}" loading="lazy"></a>`).join('')}</div>`:''}<div class="admin-row-actions"><select data-bug-status="${esc(r.id)}">${['new','in_progress','fixed','closed','rejected'].map(s=>`<option value="${s}" ${s===r.status?'selected':''}>${s}</option>`).join('')}</select><input data-bug-comment="${esc(r.id)}" maxlength="1000" value="${esc(r.internalComment)}" placeholder="Внутренний комментарий"><input data-bug-response="${esc(r.id)}" maxlength="1000" placeholder="Ответ игроку (необязательно)"><button class="admin-action" data-save-bug="${esc(r.id)}">СОХРАНИТЬ</button></div></div></article>`).join(''):'<div class="admin-empty">Новых обращений нет.</div>'}</div>`;const reload=async()=>{const q=new URLSearchParams(),s=$('bugStatusFilter').value,l=$('bugLocationFilter').value,d=$('bugDateFilter').value,p=$('bugPlayerFilter').value;if(s)q.set('status',s);if(l)q.set('location',l);if(d)q.set('day',d);if(p)q.set('player',p);renderOwnerBugs(host,await api('/api/bugs/owner?'+q));$('bugStatusFilter').value=s;$('bugLocationFilter').value=l;$('bugDateFilter').value=d;$('bugPlayerFilter').value=p;};$('reloadBugReports').onclick=reload;$('bugStatusFilter').onchange=reload;$('bugLocationFilter').onchange=reload;$('bugDateFilter').onchange=reload;$('bugPlayerFilter').onchange=reload;section.querySelectorAll('[data-save-bug]').forEach(b=>b.onclick=async()=>{try{await api('/api/bugs/owner/'+encodeURIComponent(b.dataset.saveBug),{method:'POST',body:JSON.stringify({status:section.querySelector(`[data-bug-status="${CSS.escape(b.dataset.saveBug)}"]`).value,internalComment:section.querySelector(`[data-bug-comment="${CSS.escape(b.dataset.saveBug)}"]`).value,response:section.querySelector(`[data-bug-response="${CSS.escape(b.dataset.saveBug)}"]`).value})});await reload();}catch(e){alert(errorText(e));}});}
  function renderOwner(host,sum,reports,complaints){const s=sum.summary,pending=(reports.reports||[]).filter(r=>r.status==='pending'),adminComplaints=(complaints.tickets||[]).filter(t=>!['resolved','rejected'].includes(t.status));host.innerHTML=`<div class="admin-section-title"><h3>СТАТИСТИКА ЗА СЕГОДНЯ</h3><span>00:00–00:00 · UTC+3 · автообновление</span></div><div class="owner-admin-summary">${[['ONLINE',s.online],['ВСЕГО',s.total],['ЖАЛОБЫ',s.playerReports],['ВОПРОСЫ',s.questions],['ОТЧЁТЫ',s.pendingReports],['НА АДМИНОВ',s.adminComplaints]].map(x=>`<div class="admin-stat"><small>${x[0]}</small><strong>${x[1]}</strong></div>`).join('')}</div><section class="owner-admin-section"><div class="admin-section-title"><h3>НАЗНАЧИТЬ АДМИНИСТРАТОРА</h3><span>только Owner</span></div><div class="owner-admin-assignment"><input id="ownerAdminUsername" placeholder="@nickname"><select id="ownerAdminLevel">${[1,2,3,4,5,6,7,8].map(l=>`<option value="${l}">LVL ${l} · ${rankName(l)}</option>`).join('')}</select><button id="ownerAdminAssign" class="admin-action">НАЗНАЧИТЬ</button></div></section><div class="admin-section-title"><h3>СОСТАВ</h3><span>${sum.staff.length} администраторов</span></div><div class="owner-admin-staff-grid">${sum.staff.length?sum.staff.map(ownerStaffCard).join(''):'<div class="admin-empty">Администраторов пока нет.</div>'}</div><div class="owner-admin-columns"><section class="owner-admin-section"><div class="admin-section-title"><h3>ОТЧЁТЫ НА ПРОВЕРКУ</h3><span>${pending.length}</span></div><div class="admin-list">${pending.length?pending.map(ownerReportCard).join(''):'<div class="admin-empty">Нет новых отчётов.</div>'}</div></section><section class="owner-admin-section"><div class="admin-section-title"><h3>ЖАЛОБЫ НА АДМИНИСТРАЦИЮ</h3><span>${adminComplaints.length}</span></div><div class="admin-list">${adminComplaints.length?adminComplaints.map(ownerComplaintCard).join(''):'<div class="admin-empty">Нет новых жалоб.</div>'}</div></section></div>`;
    $('ownerAdminAssign').onclick=async()=>{try{await api('/api/admin-system/owner/assign',{method:'POST',body:JSON.stringify({username:$('ownerAdminUsername').value,level:Number($('ownerAdminLevel').value)})});openOwner();}catch(e){alert(errorText(e));}};
    host.querySelectorAll('[data-rank-user]').forEach(b=>b.onclick=()=>changeRank(b.dataset.rankUser,b.closest('.admin-staff-card').querySelector('[data-rank-select]').value));host.querySelectorAll('[data-remove-user]').forEach(b=>b.onclick=()=>removeStaff(b.dataset.removeUser));host.querySelectorAll('[data-warn-user]').forEach(b=>b.onclick=()=>warnStaff(b.dataset.warnUser));host.querySelectorAll('[data-owner-suspend]').forEach(b=>b.onclick=()=>ownerSuspend(b.dataset.ownerSuspend));host.querySelectorAll('[data-owner-resume]').forEach(b=>b.onclick=()=>ownerResume(b.dataset.ownerResume));host.querySelectorAll('[data-warning-resolve]').forEach(b=>b.onclick=()=>resolveWarning(b.dataset.warningResolve));host.querySelectorAll('[data-report-review]').forEach(b=>b.onclick=()=>reviewReport(b.dataset.reportReview,b.dataset.decision));host.querySelectorAll('[data-complaint-review]').forEach(b=>b.onclick=()=>reviewComplaint(b.dataset.complaintReview,b.dataset.decision));
  }
  function ownerStaffCard(a){return `<article class="admin-staff-card ${a.online?'online':''} ${a.suspended?'suspended':''}"><div class="admin-staff-head"><div><strong>@${esc(a.username)} · LVL ${a.level}</strong><p>${esc(rankName(a.level))} · ${a.suspended?`ОТСТРАНЁН ДО ${date(a.suspendedUntil)} · ${esc(a.suspensionReason)}`:'статистика за сегодня'}</p></div>${a.online?'<span class="admin-online-dot" title="online"></span>':''}</div><div class="admin-system-grid" style="margin-top:9px"><div class="admin-stat"><small>ОНЛАЙН ЗА ДЕНЬ</small><strong>${fmtMs(a.work.activeMs)}</strong></div><div class="admin-stat"><small>ВОПРОСЫ ЗА ДЕНЬ</small><strong>${a.work.questions}</strong></div><div class="admin-stat"><small>ЖАЛОБЫ ЗА ДЕНЬ</small><strong>${a.work.reports}</strong></div><div class="admin-stat"><small>ПРИГЛАШЕНО ЗА ДЕНЬ</small><strong>${a.work.referrals}</strong></div></div><p>Баллы: ${a.work.points}/${a.work.norm} · расчёт: ${a.work.amount} CR · выплачено всего: ${Number(a.totalSalary).toLocaleString('ru-RU')} CR</p><div class="admin-row-actions"><select data-rank-select>${[1,2,3,4,5,6,7,8].map(l=>`<option value="${l}" ${l===a.level?'selected':''}>LVL ${l} · ${rankName(l)}</option>`).join('')}</select><button class="admin-action muted" data-rank-user="${a.id}">ИЗМЕНИТЬ РАНГ</button><button class="admin-action danger" data-warn-user="${a.id}">ВЫГОВОР</button>${a.suspended?`<button class="admin-action" data-owner-resume="${a.id}">ВОССТАНОВИТЬ</button>`:`<button class="admin-action danger" data-owner-suspend="${a.id}">ОТСТРАНИТЬ</button>`}<button class="admin-action danger" data-remove-user="${a.id}">СНЯТЬ</button></div>${a.notes?.length?`<div class="admin-note-list">${a.notes.slice(0,3).map(n=>`<small>${date(n.createdAt)} · @${esc(n.createdByUsername||'admin')}: ${esc(n.note)}</small>`).join('')}</div>`:''}${a.warnings.length?`<div class="admin-warning-list">${a.warnings.map(w=>`<div class="admin-warning-row"><span>${esc(w.reason)} · ${date(w.createdAt)}</span><button class="admin-action muted" data-warning-resolve="${w.id}">СНЯТЬ</button></div>`).join('')}</div>`:''}</article>`;}
  function ownerReportCard(r){return `<article class="admin-report-card"><strong>@${esc(r.username)} · ${esc(r.day)} · LVL ${r.level}</strong><p>${r.snapshot.points}/${r.snapshot.norm} баллов · ${fmtMs(r.snapshot.activeMs)} · вопросы ${r.snapshot.questions} · жалобы ${r.snapshot.reports} · приглашено ${r.snapshot.referrals}</p><p>Расчётная зарплата: <b>${Number(r.calculatedSalary).toLocaleString('ru-RU')} CR</b></p><div class="admin-row-actions"><button class="admin-action" data-report-review="${r.id}" data-decision="accepted">ПРИНЯТЬ</button><button class="admin-action danger" data-report-review="${r.id}" data-decision="rejected">ОТКЛОНИТЬ</button></div></article>`;}
  function ownerComplaintCard(t){const ev=(t.evidence||[]).length?`<div class="admin-evidence">${t.evidence.map(x=>`<img src="${esc(x)}" alt="Доказательство">`).join('')}</div>`:'';return `<article class="admin-owner-complaint"><strong>#${t.no} · на @${esc(t.targetAdmin)}</strong><p>@${esc(t.reporter)} · ${esc(t.category)} · ${esc(t.description)}</p>${ev}<div class="admin-row-actions"><button class="admin-action" data-complaint-review="${t.id}" data-decision="resolved">ЗАКРЫТЬ</button><button class="admin-action danger" data-complaint-review="${t.id}" data-decision="rejected">ОТКЛОНИТЬ</button></div></article>`;}
  async function changeRank(id,level){try{await api(`/api/admin-system/owner/staff/${id}/rank`,{method:'POST',body:JSON.stringify({level:Number(level)})});openOwner();}catch(e){alert(errorText(e));}}async function removeStaff(id){if(!confirm('Снять администратора? История сохранится.'))return;try{await api(`/api/admin-system/owner/staff/${id}/remove`,{method:'POST',body:'{}'});openOwner();}catch(e){alert(errorText(e));}}async function warnStaff(id){const reason=prompt('Причина выговора:');if(!reason)return;try{await api(`/api/admin-system/owner/staff/${id}/warning`,{method:'POST',body:JSON.stringify({reason})});openOwner();}catch(e){alert(errorText(e));}}async function resolveWarning(id){try{await api(`/api/admin-system/owner/warnings/${id}/resolve`,{method:'POST',body:'{}'});openOwner();}catch(e){alert(errorText(e));}}
  async function ownerSuspend(id){const reason=prompt('Причина временного отстранения:');if(!reason)return;const hours=Math.max(1,Number(prompt('На сколько часов? (1–8760)','24'))||24);try{await api(`/api/admin-system/owner/staff/${id}/suspend`,{method:'POST',body:JSON.stringify({reason,durationMs:Math.min(8760,hours)*3600000})});openOwner();}catch(e){alert(errorText(e));}}
  async function ownerResume(id){try{await api(`/api/admin-system/owner/staff/${id}/resume`,{method:'POST',body:'{}'});openOwner();}catch(e){alert(errorText(e));}}
  async function reviewReport(id,decision){let comment='';if(decision==='rejected'){comment=prompt('Причина отклонения отчёта (обязательно):')||'';if(!comment.trim())return;}else comment=prompt('Комментарий владельца (необязательно):')||'';try{const d=await api(`/api/admin-system/owner/reports/${id}/review`,{method:'POST',body:JSON.stringify({decision,comment})});alert(decision==='accepted'?`Отчёт принят. Выплачено ${d.paidAmount} CR.`:'Отчёт отклонён. Зарплата 0 CR.');openOwner();}catch(e){alert(errorText(e));}}
  async function reviewComplaint(id,decision){const comment=prompt('Комментарий владельца:')||'';try{await api(`/api/admin-system/owner/admin-complaints/${id}/resolve`,{method:'POST',body:JSON.stringify({status:decision,comment})});openOwner();}catch(e){alert(errorText(e));}}

  window.VelocityAdminSystem={refreshMe,openOwner,openSupport:()=>supportBtn.click(),openStaff};
})();
